test("merge reconciliation consumes only an exact governed decision and two-parent merge",()=>{const head="b".repeat(40),merge="c".repeat(40),id=stableDecisionId("e".repeat(64));const decision:any={schema_version:2,decision_key:"e".repeat(64),decision_id:id,authorization_id:spec.authorization_id,repository:spec.repository,issue:1,pr:2,base_sha:sha,head_sha:head,roadmap_id:spec.roadmap_id,roadmap_item_id:spec.roadmap_item_id,risk:"LOW",deterministic_gate:"PASS",codex_review:"PASS",review_findings_count:0,review_consistent:true,policy_decision:"APPROVE",allowed_action:"MERGE",policy_sha256:"d".repeat(64),evidence_sha256:"e".repeat(64),created_utc:new Date().toISOString()};const good:any=guarded({repo:"cesarmanuel8102/AI_Vault",json:()=>({state:"MERGED",mergeCommit:{oid:merge}}),prIdentity:()=>({state:"MERGED"}),verifyMerged:()=>merge,commentOnce:()=>true});const ledger=new Ledger(mkdtempSync(join(tmpdir(),"ledger-")));ledger.record(decision);const effects=new ProductionEffects(good,ledger,".",mkdtempSync(join(tmpdir(),"effects-")),boundary),mergeState:any={schema_version:1,front_id:spec.front_id,roadmap_item_id:spec.roadmap_item_id,state:"MERGING",issue:1,pr:2,base_sha:sha,head_sha:head,builder_session:"builder-one",reviewer_session:"reviewer-one",decision_id:id,repair_cycles:0,deployment_mode:"NO_DEPLOY",completed_effects:["issue:1",`build:${head}`],updated_utc:new Date().toISOString()};effects.bindLifecycle(spec,mergeState);effects.review=()=>({session:"reviewer-one",output:{verdict:"PASS",head_sha:head,summary:"pass",findings:[]}});effects.policy=()=>({outcome:"APPROVE",decision_id:id});assert.equal(effects.ensureMerge(2,head,sha,id),merge);assert.equal(ledger.hasHead(head),true);assert.equal(effects.ensureMerge(2,head,sha,id),merge);const wrong={...good,verifyMerged:()=>{throw new Error("governed merge parents mismatch");}};const otherLedger=new Ledger(mkdtempSync(join(tmpdir(),"ledger-")));otherLedger.record(decision);const badEffects=new ProductionEffects(guarded(wrong) as any,otherLedger,".",mkdtempSync(join(tmpdir(),"effects-")),boundary);badEffects.bindLifecycle(spec,mergeState);badEffects.review=effects.review;badEffects.policy=effects.policy;assert.throws(()=>badEffects.ensureMerge(2,head,sha,id),/parents mismatch/);assert.equal(otherLedger.hasHead(head),false);const blockedLedger=new Ledger(mkdtempSync(join(tmpdir(),"ledger-")));blockedLedger.record(decision);let mergeAttempts=0;const blockedEffects=new ProductionEffects(guarded({...good,json:()=>({state:"OPEN"}),prIdentity:()=>({state:"OPEN"}),verifyMerged:()=>{mergeAttempts++;return merge;}}) as any,blockedLedger,".",mkdtempSync(join(tmpdir(),"effects-")),boundary);blockedEffects.bindLifecycle(spec,mergeState);blockedEffects.review=effects.review;blockedEffects.policy=()=>({outcome:"BLOCK",decision_id:id});assert.throws(()=>blockedEffects.ensureMerge(2,head,sha,id),/revalidation failed/);assert.equal(mergeAttempts,0);});
test("failed governed merge corroborates both GitHub PR base representations against the advanced remote tip",()=>{const root=mkdtempSync(join(tmpdir(),"failed-merge-")),store=new LifecycleStore(join(root,"lifecycle")),ledger=new Ledger(join(root,"decisions")),head="b".repeat(40),nextBase="c".repeat(40),nextSpec={...spec,expected_base_sha:nextBase},id=stableDecisionId("e".repeat(64)),state:any={schema_version:1,front_id:spec.front_id,roadmap_item_id:spec.roadmap_item_id,state:"MERGING",issue:77,pr:78,base_sha:sha,head_sha:head,builder_session:"builder-one",reviewer_session:"reviewer-one",decision_id:id,repair_cycles:0,deployment_mode:"NO_DEPLOY",completed_effects:["issue:77",`build:${head}`],updated_utc:new Date().toISOString()},decision:any={schema_version:2,decision_key:"e".repeat(64),decision_id:id,authorization_id:spec.authorization_id,repository:spec.repository,issue:77,pr:78,base_sha:sha,head_sha:head,roadmap_id:spec.roadmap_id,roadmap_item_id:spec.roadmap_item_id,risk:"LOW",deterministic_gate:"PASS",codex_review:"PASS",review_findings_count:0,review_consistent:true,policy_decision:"APPROVE",allowed_action:"MERGE",policy_sha256:POLICY_SHA256,evidence_sha256:"e".repeat(64),created_utc:new Date().toISOString()};store.save(state);ledger.record(decision);const identity={author:{login:"cesarmanuel8102"},baseRefName:"codex/own-capital-sustainable-return",baseRefOid:sha,headRefName:spec.work_branch,headRefOid:head,headRepository:{nameWithOwner:"cesarmanuel8102/AI_Vault"},isCrossRepository:false,isDraft:true,state:"OPEN",files:[{path:"docs/x.md"}]},remoteBranchHead=(branch:string)=>branch===spec.work_branch?head:nextBase,bus:any=guarded({prIdentity:()=>identity,remoteBranchHead,failedGovernedMerge:()=>30386458671,isAncestor:()=>true});const effects=new ProductionEffects(bus,ledger,".",root,boundary);const blocked=effects.invalidateFailedMerge(nextSpec,state,store);assert.equal(blocked.state,"BLOCKED");assert.equal(blocked.decision_id,undefined);assert.equal(ledger.load(id).decision_id,id);const currentTipEffects=new ProductionEffects(guarded({...bus,prIdentity:()=>({...identity,baseRefOid:nextBase})}),ledger,".",mkdtempSync(join(tmpdir(),"failed-current-tip-")),boundary);assert.equal(currentTipEffects.invalidateFailedMerge(nextSpec,state,new LifecycleStore(mkdtempSync(join(tmpdir(),"lifecycle-")))).state,"BLOCKED");for(const patch of [{isDraft:false},{headRefOid:"d".repeat(40)},{baseRefOid:"f".repeat(40)},{author:{login:"attacker"}}]){const bad=new ProductionEffects(guarded({...bus,prIdentity:()=>({...identity,...patch})}),ledger,".",mkdtempSync(join(tmpdir(),"failed-merge-")),boundary);assert.throws(()=>bad.invalidateFailedMerge(nextSpec,state,new LifecycleStore(mkdtempSync(join(tmpdir(),"lifecycle-")))),/identity invalid/);}const noAncestor=new ProductionEffects(guarded({...bus,isAncestor:()=>false}),ledger,".",root,boundary);assert.throws(()=>noAncestor.invalidateFailedMerge(nextSpec,state,store),/identity invalid/);const wrongBaseTip=new ProductionEffects(guarded({...bus,remoteBranchHead:(branch:string)=>branch===spec.work_branch?head:"f".repeat(40)}),ledger,".",root,boundary);assert.throws(()=>wrongBaseTip.invalidateFailedMerge(nextSpec,state,store),/identity invalid/);});
